      "pre filters": [
        {
          "field": "Joint effect",
          "value": 5e-15,
          "type": "search greater than"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Joint effect vs Marginal effect",
            "raw field": "group",
            "if no value": "Gene set analysis results by gene set source"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Joint effect",
            "raw field": "beta",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "Marginal effect",
            "raw field": "beta_uncorrected",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "Gene set",
            "raw field": "gene_set"
          },
          {
            "type": "raw",
            "field name": "Number of genes in the set",
            "raw field": "n"
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype_name"
          },
          {
            "type": "raw",
            "field name": "Phenotype ID",
            "raw field": "phenotype"
          },
          {
            "type": "join multi",
            "field name": "Genes in gene set",
            "fields to join": [
              "phenotype",
              "gene_set"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "join multi",
            "field name": "Phenotype/Gene set",
            "fields to join": [
              "phenotype",
              "gene_set"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "join multi",
            "field name": "Hypothesis",
            "fields to join": [
              "phenotype",
              "gene_set"
            ],
            "join by": [
              ","
            ]
          }
        ],
        "top rows": [
          "Phenotype",
          "Phenotype ID",
          "Gene set",
          "Joint effect",
          "Marginal effect",
          "Number of genes in the set",
          "Source",
          "Genes in gene set",
          "Hypothesis"
        ],
        "tool tips": {
          "Phenotype ID": "Phenotype identifier from the Association to Function Knowledge Portal. See the Searchable options page to map identifiers to descriptive terms.",
          "Gene set": "Gene set identifier",
          "Joint effect": "The joint effect of a gene set measures its relevance to the phenotype when considered jointly across all gene sets in the model; this measure quantifies whether a gene set is maximally predictive of a phenotype compared to all other gene sets in the model. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting joint gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set. Genes with high marginal effects but weak joint effects are relevant to the phenotype in question but likely correlated with another gene set(s) that are more relevant to the phenotype.",
          "Marginal effect": "The marginal effect of a gene set measures its relevance to the phenotype when considered in isolation; this is the default measure by which the table is sorted and is the analog of traditional enrichment statistics. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting marginal gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set.",
          "Number of genes in the set": "This shows the number of genes in the set with direct genetic support, which may be slightly higher than the total number of genes in the set (as indicated by the number of rows in the “Genes in gene set” subtable.",
          "Source": "Source of the gene set",
          "Genes in gene set": "View all genes in the gene set, sorted by relevance to the phenotype (combined genetic support). Combined support incorporates both direct support (from GWAS associations near the gene) and indirect support (membership in gene sets with genetic support). All measures of genetic support are in units of log-odds of probability. Consider the following thresholds for interpreting  genetic support scores: 1-nominally significant, 2-strongly suggestive (i.e., indicative that a gene is in a locus but not yet genome-wide significant), and 3-very strong (>50% probability that a gene is involved in the phenotype; similar to nearest gene to a GWAS signal).",
          "Hypothesis": "Use GPT-4o to suggest how the 10 genes within this set most associated with the phenotype are related to the phenotype, using the gene set as context to the query. The subtable shows the response from GPT-4o as well as the input prompt, so that it can be copied into your favorite ChatBot to initiate further lines of inquiry."
        },
        "column formatting": {
          "Hypothesis": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://llm.hugeamp.org/llm?phenotype=$phenotype&gene_set=$geneSet&gene_limit=10&add_context=1",
                "parameters": [
                  "phenotype",
                  "geneSet"
                ],
                "parameters type": "replace",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Hypothesis",
                    "raw field": "gpt_response"
                  },
                  {
                    "type": "raw",
                    "field name": "LLM Query",
                    "raw field": "query"
                  }
                ],
                "top rows": [
                  "LLM Query",
                  "Hypothesis"
                ],
                "column formatting": {
                  "LLM Query": {
                    "type": [
                      "copy to clipboard"
                    ]
                  },
                  "Hypothesis": {
                    "type": [
                      "copy to clipboard"
                    ]
                  }
                }
              }
            }
          },
          "Source": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_gene_set_browser_source?source="
          },
          "Phenotype ID": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_gene_set_browser_phenotype?phenotype=",
            "new tab": "true"
          },
          "Gene set": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_gene_set_browser_gene_set?geneSet=",
            "new tab": "true"
          },
          "Genes in gene set": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde.hugeampkpnbi.org/api/bio/",
                "index": "pigean-joined-gene-set",
                "parameters": [
                  "phenotype",
                  "geneSet"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Gene",
                    "raw field": "gene"
                  },
                  {
                    "type": "raw",
                    "field name": "Combined genetic support",
                    "raw field": "combined"
                  },
                  {
                    "type": "raw",
                    "field name": "Direct genetic support",
                    "raw field": "log_bf"
                  },
                  {
                    "type": "raw",
                    "field name": "Indirect genetic support",
                    "raw field": "prior"
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  }
                ],
                "top rows": [
                  "Gene",
                  "Combined genetic support",
                  "Direct genetic support",
                  "Indirect genetic support"
                ],
                "column formatting": {
                  "Gene": {
                    "type": [
                      "link"
                    ],
                    "link to": "/r/kc_gene_set_browser_gene?gene=",
                    "new tab": "true"
                  }
                }
              }
            }
          }
        }
      },
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "Phenotype/Gene set",
            "type": "scatter plot",
            "star key": null,
            "render type": "single plot",
            "group by": "Joint effect vs Marginal effect",
            "color by": "Source",
            "y axis field": "Joint effect",
            "y axis label": "Joint effect",
            "x axis field": "Marginal effect",
            "x axis label": "Marginal effect",
            "ticks decimal point": "4",
            "render by": "Phenotype/Gene set",
            "hover content": [
              "Phenotype",
              "Gene set",
              "Joint effect",
              "Marginal effect",
              "Number of genes in the set"
            ],
            "height": 200,
            "width": 550,
            "plot margin": {
              "left": 60,
              "right": 20,
              "top": 40,
              "bottom": 50,
              "bump": 5
            }
          }
        ]
      }
    }
  ]
}

